import { describe, it, expect, beforeEach, vi } from 'vitest'
import { fetchAssignments } from '../lib/canvas'
import { useTaskStore } from './taskStore'

vi.mock('../lib/canvas', () => ({
  fetchAssignments: vi.fn(),
}))

describe('taskStore', () => {
  beforeEach(() => {
    // Reset store state before each test
    useTaskStore.setState({
      tasks: [],
      lastFetched: null,
      syncing: false,
      error: null,
      courseAliases: {},
      customOrder: [],
      customCourses: [],
    })
    vi.mocked(fetchAssignments).mockReset()
  })

  describe('addManualTask', () => {
    it('adds a new manual task with default course', () => {
      const { addManualTask } = useTaskStore.getState()

      addManualTask('Test task', null)

      const { tasks } = useTaskStore.getState()
      expect(tasks).toHaveLength(1)
      expect(tasks[0]).toMatchObject({
        title: 'Test task',
        dueDate: null,
        courseName: 'Personal',
        source: 'manual',
        completed: false,
      })
      expect(tasks[0].id).toMatch(/^manual-[0-9a-f-]{36}$/)
    })

    it('adds a task with due date and custom course', () => {
      const { addManualTask } = useTaskStore.getState()

      addManualTask('Task with date', '2025-02-15', 'Math')

      const { tasks } = useTaskStore.getState()
      expect(tasks[0]).toMatchObject({
        title: 'Task with date',
        dueDate: '2025-02-15',
        courseName: 'Math',
      })
    })

    it('keeps IDs unique when tasks are created in the same millisecond', () => {
      const now = vi.spyOn(Date, 'now').mockReturnValue(1_700_000_000_000)
      const { addManualTask } = useTaskStore.getState()

      addManualTask('First task', null)
      addManualTask('Second task', null)

      const ids = useTaskStore.getState().tasks.map(task => task.id)
      expect(new Set(ids).size).toBe(2)
      now.mockRestore()
    })
  })

  describe('toggleComplete', () => {
    it('toggles task completion status', () => {
      useTaskStore.setState({
        tasks: [
          { id: 'test-1', title: 'Task 1', dueDate: null, courseName: 'Personal', source: 'manual', completed: false },
        ],
      })

      const { toggleComplete } = useTaskStore.getState()

      toggleComplete('test-1')
      expect(useTaskStore.getState().tasks[0].completed).toBe(true)

      toggleComplete('test-1')
      expect(useTaskStore.getState().tasks[0].completed).toBe(false)
    })

    it('does not affect other tasks', () => {
      useTaskStore.setState({
        tasks: [
          { id: 'test-1', title: 'Task 1', dueDate: null, courseName: 'Personal', source: 'manual', completed: false },
          { id: 'test-2', title: 'Task 2', dueDate: null, courseName: 'Personal', source: 'manual', completed: true },
        ],
      })

      const { toggleComplete } = useTaskStore.getState()
      toggleComplete('test-1')

      const { tasks } = useTaskStore.getState()
      expect(tasks[0].completed).toBe(true)
      expect(tasks[1].completed).toBe(true)
    })
  })

  describe('syncCanvas', () => {
    it('preserves completion by assignment identity, not a shared title', async () => {
      useTaskStore.setState({
        tasks: [
          {
            id: 'canvas-school-a:101',
            title: 'Final Project',
            dueDate: '2025-02-10T12:00:00Z',
            courseName: 'Course A',
            source: 'canvas',
            completed: true,
          },
          {
            id: 'canvas-school-a:202',
            title: 'Final Project',
            dueDate: '2025-02-11T12:00:00Z',
            courseName: 'Course B',
            source: 'canvas',
            completed: false,
          },
        ],
      })
      vi.mocked(fetchAssignments).mockResolvedValue([
        {
          id: 'school-a:101',
          name: 'Renamed Final Project',
          due_at: '2025-02-12T12:00:00Z',
          course_id: '1',
          course_name: 'Course A',
        },
        {
          id: 'school-a:202',
          name: 'Final Project',
          due_at: '2025-02-13T12:00:00Z',
          course_id: '2',
          course_name: 'Course B',
        },
      ])

      await useTaskStore.getState().syncCanvas(true)

      expect(useTaskStore.getState().tasks).toEqual([
        expect.objectContaining({
          id: 'canvas-school-a:101',
          title: 'Renamed Final Project',
          completed: true,
        }),
        expect.objectContaining({
          id: 'canvas-school-a:202',
          title: 'Final Project',
          completed: false,
        }),
      ])
    })
  })

  describe('reorderTasks', () => {
    it('reorders tasks based on drag position', () => {
      useTaskStore.setState({
        tasks: [
          { id: 'test-1', title: 'Task 1', dueDate: null, courseName: 'Personal', source: 'manual', completed: false },
          { id: 'test-2', title: 'Task 2', dueDate: null, courseName: 'Personal', source: 'manual', completed: false },
          { id: 'test-3', title: 'Task 3', dueDate: null, courseName: 'Personal', source: 'manual', completed: false },
        ],
        customOrder: [],
      })

      const { reorderTasks } = useTaskStore.getState()

      // Move task-1 to position of task-3
      reorderTasks('test-1', 'test-3')

      const { customOrder } = useTaskStore.getState()
      expect(customOrder).toEqual(['test-2', 'test-3', 'test-1'])
    })

    it('initializes customOrder from tasks if empty', () => {
      useTaskStore.setState({
        tasks: [
          { id: 'test-1', title: 'Task 1', dueDate: null, courseName: 'Personal', source: 'manual', completed: false },
          { id: 'test-2', title: 'Task 2', dueDate: null, courseName: 'Personal', source: 'manual', completed: false },
        ],
        customOrder: [],
      })

      const { reorderTasks } = useTaskStore.getState()
      reorderTasks('test-2', 'test-1')

      const { customOrder } = useTaskStore.getState()
      expect(customOrder).toContain('test-1')
      expect(customOrder).toContain('test-2')
    })
  })

  describe('addCustomCourse', () => {
    it('adds a new custom course', () => {
      const { addCustomCourse } = useTaskStore.getState()

      addCustomCourse('My Course')

      const { customCourses } = useTaskStore.getState()
      expect(customCourses).toContain('My Course')
    })

    it('trims whitespace from course name', () => {
      const { addCustomCourse } = useTaskStore.getState()

      addCustomCourse('  Spaced Course  ')

      const { customCourses } = useTaskStore.getState()
      expect(customCourses).toContain('Spaced Course')
    })

    it('does not add duplicate courses', () => {
      useTaskStore.setState({ customCourses: ['Existing'] })

      const { addCustomCourse } = useTaskStore.getState()
      addCustomCourse('Existing')

      const { customCourses } = useTaskStore.getState()
      expect(customCourses).toEqual(['Existing'])
    })

    it('does not add empty course names', () => {
      const { addCustomCourse } = useTaskStore.getState()

      addCustomCourse('')
      addCustomCourse('   ')

      const { customCourses } = useTaskStore.getState()
      expect(customCourses).toEqual([])
    })
  })

})

import { create } from 'zustand'
import { persist } from 'zustand/middleware'
import { fetchAssignments, type CanvasAssignment } from '../lib/canvas'
import type { Task } from '../schemas/task'

export type { Task }

export type DeleteStrategy =
  | { type: 'keep' }
  | { type: 'reassign'; target: string }
  | { type: 'delete' }

interface TaskStore {
  tasks: Task[]
  lastFetched: number | null
  syncing: boolean
  error: string | null
  courseAliases: Record<string, string>
  customOrder: string[]
  customCourses: string[]

  syncCanvas: (force?: boolean) => Promise<void>
  toggleComplete: (id: string) => void
  addManualTask: (title: string, dueDate: string | null, courseName?: string) => void
  deleteTask: (id: string) => void
  setCourseAlias: (original: string, alias: string) => void
  reorderTasks: (activeId: string, overId: string) => void
  addCustomCourse: (name: string) => void
  renameCourse: (courseName: string, newDisplayName: string) => void
  deleteCourse: (courseName: string, strategy: DeleteStrategy) => void
}

const STALE_THRESHOLD = 60 * 60 * 1000 // 1 hour

export const useTaskStore = create<TaskStore>()(
  persist(
    (set, get) => ({
      tasks: [],
      lastFetched: null,
      syncing: false,
      error: null,
      courseAliases: {},
      customOrder: [],
      customCourses: [],

      syncCanvas: async (force = false) => {
        const { lastFetched, syncing } = get()

        // Prevent concurrent syncs or syncing if data is fresh
        if (syncing) return
        if (!force && lastFetched && Date.now() - lastFetched < STALE_THRESHOLD) return

        set({ syncing: true, error: null })

        try {
          const assignments = await fetchAssignments()
          const canvasTasks = assignments.map(transformToTask)

          // Dedupe canvas tasks by ID
          const seenIds = new Set<string>()
          const uniqueCanvasTasks = canvasTasks.filter(t => {
            if (seenIds.has(t.id)) return false
            seenIds.add(t.id)
            return true
          })

          // Merge: keep manual tasks + completion state, update canvas tasks
          const { tasks: existingTasks } = get()
          const manualTasks = existingTasks.filter(t => t.source === 'manual')

          // Canvas IDs include both the configured instance and assignment ID.
          // Titles are not identities: two courses commonly reuse names such as
          // "Final Project" or "Week 1 Discussion".
          const completedCanvasIds = new Set(
            existingTasks
              .filter(t => t.source === 'canvas' && t.completed)
              .map(t => t.id)
          )

          const mergedCanvasTasks = uniqueCanvasTasks.map(t => ({
            ...t,
            completed: completedCanvasIds.has(t.id)
          }))

          set({
            tasks: [...mergedCanvasTasks, ...manualTasks],
            lastFetched: Date.now(),
            syncing: false,
          })
        } catch (err) {
          set({
            error: err instanceof Error ? err.message : 'Sync failed',
            syncing: false
          })
        }
      },

      toggleComplete: (id) => set((state) => ({
        tasks: state.tasks.map(t =>
          t.id === id ? { ...t, completed: !t.completed } : t
        )
      })),

      addManualTask: (title, dueDate, courseName = 'Personal') => set((state) => ({
        tasks: [...state.tasks, {
          id: `manual-${crypto.randomUUID()}`,
          title,
          dueDate,
          courseName,
          source: 'manual' as const,
          completed: false,
        }]
      })),

      deleteTask: (id) => set((state) => ({
        tasks: state.tasks.filter(t => t.id !== id),
        customOrder: state.customOrder.filter(orderId => orderId !== id),
      })),

      setCourseAlias: (original, alias) => set((state) => ({
        courseAliases: {
          ...state.courseAliases,
          [original]: alias.trim() || original,
        }
      })),

      reorderTasks: (activeId, overId) => set((state) => {
        // If items aren't in customOrder yet, initialize from current task order
        let order = [...state.customOrder]
        const taskIds = state.tasks.map(t => t.id)

        // Add any missing task IDs to the order
        for (const id of taskIds) {
          if (!order.includes(id)) {
            order.push(id)
          }
        }
        // Remove any IDs no longer in tasks
        order = order.filter(id => taskIds.includes(id))

        const activeIdx = order.indexOf(activeId)
        const overIdx = order.indexOf(overId)

        if (activeIdx === -1 || overIdx === -1) return state

        // Move item from old position to new position
        order.splice(activeIdx, 1)
        order.splice(overIdx, 0, activeId)

        return { customOrder: order }
      }),

      addCustomCourse: (name) => set((state) => {
        const trimmed = name.trim()
        if (!trimmed || state.customCourses.includes(trimmed)) return state
        return { customCourses: [...state.customCourses, trimmed] }
      }),

      renameCourse: (courseName, newDisplayName) => set((state) => {
        const trimmed = newDisplayName.trim()
        if (!trimmed || trimmed === 'Personal') return state

        const hasCanvasTasks = state.tasks.some(
          t => t.source === 'canvas' && t.courseName === courseName
        )

        if (hasCanvasTasks) {
          // Canvas or mixed: use alias
          return {
            courseAliases: { ...state.courseAliases, [courseName]: trimmed }
          }
        }

        // Manual-only: rename directly on tasks and in customCourses
        return {
          tasks: state.tasks.map(t =>
            t.courseName === courseName ? { ...t, courseName: trimmed } : t
          ),
          customCourses: state.customCourses.map(c =>
            c === courseName ? trimmed : c
          ),
        }
      }),

      deleteCourse: (courseName, strategy) => set((state) => {
        let tasks = state.tasks
        let customOrder = state.customOrder

        switch (strategy.type) {
          case 'keep':
            tasks = tasks.map(t =>
              t.courseName === courseName ? { ...t, courseName: 'Personal' } : t
            )
            break
          case 'reassign':
            tasks = tasks.map(t =>
              t.courseName === courseName ? { ...t, courseName: strategy.target } : t
            )
            break
          case 'delete': {
            const deletedIds = new Set(
              tasks.filter(t => t.courseName === courseName).map(t => t.id)
            )
            tasks = tasks.filter(t => t.courseName !== courseName)
            customOrder = customOrder.filter(id => !deletedIds.has(id))
            break
          }
        }

        const { [courseName]: _, ...remainingAliases } = state.courseAliases

        return {
          tasks,
          customOrder,
          customCourses: state.customCourses.filter(c => c !== courseName),
          courseAliases: remainingAliases,
        }
      }),
    }),
    { name: 'school-checklist-tasks' }
  )
)

function transformToTask(assignment: CanvasAssignment): Task {
  return {
    id: `canvas-${assignment.id}`,
    title: assignment.name,
    dueDate: assignment.due_at,
    courseName: assignment.course_name,
    source: 'canvas',
    completed: false,
  }
}
